"""Self-contained offline canvas viewer; exact saved sites/states, no interpolation."""
import json

def write_viewer(out,sim,records,states):
    cr=sim.crystal
    data=dict(hf=cr.hf.tolist(),oxygen=cr.oxygen.tolist(),vacancy=[x.astype(int).tolist() for x in states],records=records,cell=cr.cell.tolist(),temperature_K=sim.cfg.temperature_K,bond_cutoff_A=sim.cfg.bond_cutoff_A)
    html=r'''<!doctype html><meta charset="utf-8"><title>Monoclinic HfO2 — atomistic site KMC</title>
<style>body{margin:0;background:#0e1627;color:#dce6f5;font:15px system-ui}header{padding:18px 26px;background:#15213a}h1{font-size:23px;margin:0 0 5px}.sub{color:#b2bfd4}main{display:flex;height:calc(100vh - 95px)}canvas{width:75%;height:100%;background:radial-gradient(ellipse,#182943,#0d1424);touch-action:none}aside{box-sizing:border-box;width:25%;min-width:260px;padding:24px;background:#121d32}label{display:block;margin:20px 0}input[type=range]{width:100%}button{padding:9px 16px;background:#416ab4;color:white;border:0;border-radius:5px;cursor:pointer}p{line-height:1.6}.warning{color:#e8b974;font-size:13px;border-top:1px solid #405068;padding-top:18px}.value{font:14px monospace;white-space:pre-line}a{color:#90baff}</style>
<header><h1>Monoclinic HfO₂ · crystallographic oxygen-site KMC</h1><div class="sub">Real P2₁/c positions · drag to rotate · discrete saved states · illustrative kinetics, not validated SET/RESET</div></header>
<main><canvas id="scene"></canvas><aside><button id="play">Play saved states</button><label>Saved state <span id="counter"></span><input id="frame" type="range" min="0" value="0"></label><label><input id="oxygen" type="checkbox" checked> Show occupied oxygen</label><label><input id="hafnium" type="checkbox" checked> Show Hf framework</label><label><input id="bonds" type="checkbox" checked> Show Hf–O bonds</label><div class="value" id="stats"></div><p><span style="color:#739acb">● Hf</span> &nbsp; <span style="color:#e47171">● O</span><br><span style="color:#ffb64e">○ Oxygen vacancy</span> = missing oxygen, not an atom</p><p class="warning">Fixed single-crystal lattice. No atom relaxation, grain boundaries or amorphous phase. Geometric candidate hops are not NEB paths. Isothermal <span id="temp"></span> K; rates and electronic conductance are uncalibrated.<br><a href="https://doi.org/10.1107/S2053229620013960">Crystal source: Pathak et al. (2020)</a></p></aside></main>
<script>const D=DATA;
const c=document.getElementById('scene'),ctx=c.getContext('2d'),slider=document.getElementById('frame');slider.max=D.vacancy.length-1;document.getElementById('temp').textContent=D.temperature_K;
let yaw=-.55,pitch=.30,drag=false,prev=[0,0],timer=null;
const all=D.hf.concat(D.oxygen),lo=[0,1,2].map(k=>Math.min(...all.map(p=>p[k]))),hi=[0,1,2].map(k=>Math.max(...all.map(p=>p[k]))),center=lo.map((v,k)=>(v+hi[k])/2),span=Math.max(...hi.map((v,k)=>v-lo[k]));
const bond=[];D.hf.forEach((h,i)=>D.oxygen.forEach((o,j)=>{if(Math.hypot(...h.map((v,k)=>v-o[k]))<D.bond_cutoff_A)bond.push([i,j])}));
function project(p){let [x,y,z]=p.map((v,k)=>v-center[k]);let u=x*Math.cos(yaw)-y*Math.sin(yaw),v=x*Math.sin(yaw)+y*Math.cos(yaw);let zz=z*Math.cos(pitch)-v*Math.sin(pitch),depth=z*Math.sin(pitch)+v*Math.cos(pitch);const s=Math.min(c.width,c.height)*.68/span;return [c.width/2+u*s,c.height/2-zz*s,depth]}
function line(a,b,color,width){a=project(a);b=project(b);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(a[0],a[1]);ctx.lineTo(b[0],b[1]);ctx.stroke()}
function draw(){c.width=c.clientWidth*devicePixelRatio;c.height=c.clientHeight*devicePixelRatio;ctx.clearRect(0,0,c.width,c.height);const n=+slider.value,vac=D.vacancy[n],rec=D.records[n],hf=document.getElementById('hafnium').checked,ox=document.getElementById('oxygen').checked;
 const verts=[];for(let i=0;i<2;i++)for(let j=0;j<2;j++)for(let k=0;k<2;k++)verts.push([0,1,2].map(a=>i*D.cell[0][a]+j*D.cell[1][a]+k*D.cell[2][a]));for(let i=0;i<8;i++)for(let j=i+1;j<8;j++)if([1,2,4].includes(i^j))line(verts[i],verts[j],'#536581',devicePixelRatio);
 if(document.getElementById('bonds').checked&&hf&&ox)bond.forEach(([i,j])=>{if(!vac[j])line(D.hf[i],D.oxygen[j],'#64758c66',.7*devicePixelRatio)});
 let pts=[];if(hf)D.hf.forEach(p=>pts.push({p:project(p),r:4,color:'#739acb'}));D.oxygen.forEach((p,j)=>{if(vac[j]||ox)pts.push({p:project(p),r:vac[j]?6:2.7,color:vac[j]?'#ffb64e':'#e47171',ring:!!vac[j]})});pts.sort((a,b)=>a.p[2]-b.p[2]);pts.forEach(q=>{ctx.beginPath();ctx.arc(q.p[0],q.p[1],q.r*devicePixelRatio,0,Math.PI*2);if(q.ring){ctx.strokeStyle=q.color;ctx.lineWidth=2*devicePixelRatio;ctx.stroke()}else{ctx.fillStyle=q.color;ctx.fill()}});
 document.getElementById('counter').textContent=(n+1)+' / '+D.vacancy.length;
 document.getElementById('stats').textContent='Time: '+(rec.time_s*1e6).toFixed(4)+' µs\nEvents: '+rec.events+'\nApplied bias: '+rec.applied_V+' V\nVacancies: '+rec.vacancies+'\nReservoir oxygen: '+rec.reservoir_oxygen+'\nOxide oxygen: '+rec.oxide_oxygen+'\nTotal oxygen: '+rec.total_oxygen+'\nConductance: '+rec.conductance_S.toExponential(3)+' S\nSpanning vacancy graph: '+rec.spanning;
}
c.onpointerdown=e=>{drag=true;prev=[e.clientX,e.clientY];c.setPointerCapture(e.pointerId)};c.onpointerup=()=>drag=false;c.onpointermove=e=>{if(drag){yaw+=(e.clientX-prev[0])*.007;pitch+=(e.clientY-prev[1])*.007;prev=[e.clientX,e.clientY];draw()}};
slider.oninput=draw;['oxygen','hafnium','bonds'].forEach(x=>document.getElementById(x).onchange=draw);onresize=draw;
document.getElementById('play').onclick=function(){if(timer){clearInterval(timer);timer=null;this.textContent='Play saved states'}else{this.textContent='Pause';timer=setInterval(()=>{slider.value=(+slider.value+1)%D.vacancy.length;draw()},700)}};draw();</script>'''
    (out/'viewer.html').write_text(html.replace('DATA',json.dumps(data)))
